ALTER TABLE public.pacientes ADD COLUMN nascimento date, ADD COLUMN cadastro_raw jsonb, ADD COLUMN cadastro_sincronizado_em timestamptz;
CREATE TABLE public.lab_paciente_sync_estado(paciente_id bigint PRIMARY KEY, tentado_em timestamptz NOT NULL DEFAULT now(), erro text);
GRANT SELECT ON public.lab_paciente_sync_estado TO authenticated; GRANT ALL ON public.lab_paciente_sync_estado TO service_role;
ALTER TABLE public.lab_paciente_sync_estado ENABLE ROW LEVEL SECURITY;
CREATE POLICY paciente_sync_read ON public.lab_paciente_sync_estado FOR SELECT TO authenticated USING(true);
CREATE TABLE public.lab_paciente_geo_fila(paciente_id bigint PRIMARY KEY, status text NOT NULL DEFAULT 'pendente', tentativas integer NOT NULL DEFAULT 0, erro text, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lab_paciente_geo_fila TO authenticated; GRANT ALL ON public.lab_paciente_geo_fila TO service_role;
ALTER TABLE public.lab_paciente_geo_fila ENABLE ROW LEVEL SECURITY;
CREATE POLICY paciente_geo_read ON public.lab_paciente_geo_fila FOR SELECT TO authenticated USING(true);
CREATE TABLE public.lab_geo_cidades(chave text PRIMARY KEY,cidade text NOT NULL,estado text NOT NULL,latitude numeric,longitude numeric,atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.lab_geo_cidades TO authenticated; GRANT ALL ON public.lab_geo_cidades TO service_role;
ALTER TABLE public.lab_geo_cidades ENABLE ROW LEVEL SECURITY;
CREATE POLICY geo_cidades_read ON public.lab_geo_cidades FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.lab_enfileirar_paciente_geo() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR ROW(NEW.cep,NEW.bairro,NEW.cidade,NEW.estado) IS DISTINCT FROM ROW(OLD.cep,OLD.bairro,OLD.cidade,OLD.estado) OR NEW.cadastro_sincronizado_em IS DISTINCT FROM OLD.cadastro_sincronizado_em THEN INSERT INTO public.lab_paciente_geo_fila(paciente_id) VALUES(NEW.paciente_id) ON CONFLICT(paciente_id) DO UPDATE SET status='pendente',tentativas=0,erro=null,atualizado_em=now(); END IF; RETURN NEW; END; $$;
CREATE TRIGGER lab_paciente_geo_queue AFTER INSERT OR UPDATE OF cep,bairro,cidade,estado,cadastro_sincronizado_em ON public.pacientes FOR EACH ROW EXECUTE FUNCTION public.lab_enfileirar_paciente_geo();
CREATE OR REPLACE VIEW public.lab_vw_pacientes_pendentes WITH(security_invoker=true) AS WITH ids AS (SELECT paciente_id FROM public.lab_producao_feegow WHERE paciente_id>0 UNION SELECT paciente_id FROM public.agendamentos WHERE paciente_id>0) SELECT i.paciente_id,p.paciente_id IS NULL sem_cadastro FROM ids i LEFT JOIN public.pacientes p ON p.paciente_id=i.paciente_id LEFT JOIN public.lab_paciente_sync_estado s ON s.paciente_id=i.paciente_id WHERE (p.paciente_id IS NULL OR coalesce(p.cadastro_sincronizado_em,p.updated_at)<now()-interval '60 days') AND (s.erro IS NULL OR s.tentado_em<now()-interval '1 day');
GRANT SELECT ON public.lab_vw_pacientes_pendentes TO authenticated,service_role; REVOKE ALL ON public.lab_vw_pacientes_pendentes FROM anon;
CREATE OR REPLACE VIEW public.lab_sync_status WITH(security_invoker=true) AS SELECT * FROM public.lab_vw_sync_etapas UNION ALL SELECT 'pacientes'::text,'Cadastro de pacientes'::text,max(executado_em) FILTER(WHERE api_success),max(executado_em),coalesce((SELECT registros FROM public.lab_sync_log WHERE endpoint='sync:pacientes' AND api_success ORDER BY executado_em DESC LIMIT 1),0),coalesce(max(executado_em) FILTER(WHERE api_success)<now()-interval '2 hours',true) FROM public.lab_sync_log WHERE endpoint='sync:pacientes';
GRANT SELECT ON public.lab_sync_status TO authenticated,service_role; REVOKE ALL ON public.lab_sync_status FROM anon;
CREATE INDEX lab_patient_geo_pending_idx ON public.lab_paciente_geo_fila(status,atualizado_em);